main.script:
(function () {
  'use strict';
  /* HOME (hm-): branching routes, module line, checklist, tremor field, photo strip,
     event time rail, practitioner web. Runs after main.js has rendered its content. */
  var NS = 'http://www.w3.org/2000/svg';
  var EASE = 'cubic-bezier(.33,1,.68,1)';
  var MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var CHEV = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m9 6 6 6-6 6"/></svg>';
  var L = {}, REDUCED = false, FINE = false, relayouts = [];

  function $(s, c) { return (c || document).querySelector(s); }
  function $all(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }
  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function safe(fn) { try { fn(); } catch (e) { if (window.console && console.warn) console.warn('[home]', e); } }
  function f1(n) { return Math.round(n * 10) / 10; }
  function box(el, ref) {
    var r = el.getBoundingClientRect();
    return { x: r.left - ref.left + r.width / 2, y: r.top - ref.top + r.height / 2, l: r.left - ref.left, t: r.top - ref.top, r: r.right - ref.left, b: r.bottom - ref.top, w: r.width, h: r.height };
  }
  function mkSvg(host, cls) { var s = document.createElementNS(NS, 'svg'); s.setAttribute('class', cls); s.setAttribute('aria-hidden', 'true'); s.setAttribute('focusable', 'false'); host.appendChild(s); return s; }
  function fit(s, host) {
    var w = Math.max(1, host.clientWidth), h = Math.max(1, host.offsetHeight);
    s.setAttribute('width', w); s.setAttribute('height', h); s.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    while (s.firstChild) s.removeChild(s.firstChild);
  }
  function mkPath(s, d, cls) { var p = document.createElementNS(NS, 'path'); p.setAttribute('d', d); if (cls) p.setAttribute('class', cls); s.appendChild(p); return p; }
  function curve(x0, y0, x1, y1, k) { var dy = (y1 - y0) * (k || 0.55); return 'M' + f1(x0) + ' ' + f1(y0) + 'C' + f1(x0) + ' ' + f1(y0 + dy) + ' ' + f1(x1) + ' ' + f1(y1 - dy) + ' ' + f1(x1) + ' ' + f1(y1); }
  function lenOf(p) { try { return Math.ceil(p.getTotalLength()) + 2; } catch (e) { return 3000; } }
  function hide(p) { var n = lenOf(p); p.style.transition = 'none'; p.style.strokeDasharray = n + ' ' + n; p.style.strokeDashoffset = String(n); }
  function draw(p, dur, delay) {                       /* one-shot stroke draw, ease-out */
    if (REDUCED) return;
    hide(p); p.getBoundingClientRect();
    requestAnimationFrame(function () {
      p.style.transition = 'stroke-dashoffset ' + dur + 'ms ' + EASE + ' ' + (delay || 0) + 'ms';
      p.style.strokeDashoffset = '0';
    });
  }
  function at(f, dur, delay) { return (delay || 0) + dur * (1 - Math.pow(1 - clamp(f, 0, 1), 1 / 3)); } /* when an ease-out draw reaches fraction f */
  function later(ms, fn) { return setTimeout(fn, Math.max(0, ms)); }
  /* run fn once as el enters; under reduced motion (or without IntersectionObserver) everything is simply shown */
  function watch(el, fn) {
    if (!el) return;
    var run = function (still) { el.classList.add('hm-in'); if (fn) safe(function () { fn(still); }); };
    if (REDUCED || !('IntersectionObserver' in window)) { run(true); return; }
    el.classList.add('hm-armed');
    var io = new IntersectionObserver(function (entries) {
      for (var i = 0; i < entries.length; i++) if (entries[i].isIntersecting) { io.disconnect(); run(false); return; }
    }, { threshold: 0, rootMargin: '0px 0px -14% 0px' });
    io.observe(el);
  }
  /* size changes are handled once they have settled (trailing debounce); each caller then compares the size
     with the one it last laid out at, so transient states (tab restore, capture, a tab switch) never leave stale lines */
  function observeSize(el, fn) {
    var t = 0;
    var go = function () { t = 0; if (el.clientWidth >= 160) safe(fn); };
    var kick = function () { clearTimeout(t); t = setTimeout(go, 220); };
    if ('ResizeObserver' in window) new ResizeObserver(kick).observe(el); else window.addEventListener('resize', kick);
    relayouts.push(fn);
  }
  function sizeOf(el) { return el.clientWidth + 'x' + el.offsetHeight; }

  /* ---------- 2 · two routes from one origin ---------- */
  function fork() {
    var root = $('[data-hm-fork]'); if (!root) return;
    var origin = $('.hm-origin', root), wrap = $('.hm-routes', root), routes = $all('.hm-route', root);
    if (!origin || !wrap || routes.length !== 2) return;
    var mq = window.matchMedia('(max-width: 900px)');
    var on = 0, entered = false, laid = '', timers = [];
    var seg = document.createElement('div'); seg.className = 'hm-seg'; seg.setAttribute('data-on', '0');
    var btns = routes.map(function (r, i) {
      var b = document.createElement('button'), t = $('.hm-route-title', r);
      b.type = 'button'; b.className = 'hm-seg-btn'; b.id = 'hm-seg-' + i;
      b.textContent = t ? t.textContent.replace(/\s+/g, ' ').trim() : '';
      b.setAttribute('aria-controls', r.id);
      b.addEventListener('click', function () { setOn(i); });
      seg.appendChild(b); return b;
    });
    seg.addEventListener('keydown', function (e) {
      if (['ArrowRight', 'ArrowLeft', 'Home', 'End'].indexOf(e.key) < 0 || !mq.matches) return;
      e.preventDefault(); var n = e.key === 'Home' ? 0 : e.key === 'End' ? 1 : 1 - on; setOn(n); btns[n].focus();
    });
    wrap.parentNode.insertBefore(seg, wrap);
    var svg = mkSvg(root, 'hm-fork-svg');
    root.classList.add('hm-has-svg', 'hm-tabbed'); root.setAttribute('data-on', '0');

    function roles() {
      var tabs = mq.matches;
      if (tabs) seg.setAttribute('role', 'tablist'); else seg.removeAttribute('role');
      btns.forEach(function (b, i) {
        if (tabs) { b.setAttribute('role', 'tab'); b.setAttribute('aria-selected', String(i === on)); b.tabIndex = i === on ? 0 : -1; routes[i].setAttribute('role', 'tabpanel'); routes[i].setAttribute('aria-labelledby', b.id); }
        else { b.removeAttribute('role'); b.removeAttribute('aria-selected'); b.removeAttribute('tabindex'); routes[i].removeAttribute('role'); routes[i].removeAttribute('aria-labelledby'); }
      });
    }
    function clearT() { timers.forEach(clearTimeout); timers = []; }
    function lightAll(r) { $all('.hm-node,.hm-port', r).forEach(function (n) { n.classList.add('hm-lit'); }); $all('.hm-row', r).forEach(function (w) { w.classList.add('hm-shown'); }); }
    function unlight(r) { $all('.hm-node,.hm-port', r).forEach(function (n) { n.classList.remove('hm-lit'); }); $all('.hm-row', r).forEach(function (w) { w.classList.remove('hm-shown'); }); }
    function schedule(spec, dur, delay) {                 /* light each node (and its row) as the line reaches it */
      spec.stops.forEach(function (s) {
        var row = s.el.closest('.hm-row');
        timers.push(later(at(s.f, dur, delay) - 40, function () {
          s.el.classList.add('hm-lit');
          if (!row) return;
          row.classList.add('hm-shown');
          var nx = row.nextElementSibling;
          if (row.classList.contains('hm-route-title') && nx && nx.classList.contains('hm-row')) timers.push(later(140, function () { nx.classList.add('hm-shown'); }));
        }));
      });
    }
    function layout(mode) {
      laid = sizeOf(root);
      fit(svg, root);
      var ref = root.getBoundingClientRect(), o = box(origin, ref), tabs = mq.matches, specs = [];
      routes.forEach(function (r, i) {
        var nodes = $all('.hm-node', r); if (!nodes.length) return;
        var shown = r.offsetParent !== null;
        var n0 = shown ? box(nodes[0], ref) : null, nZ = shown ? box(nodes[nodes.length - 1], ref) : null;
        var armD, inner = null, stops = [];
        if (tabs) {
          var b = box(btns[i], ref);
          armD = curve(o.x, o.y, b.x, b.t + 2, 0.6);
          if (shown) {
            inner = 'M' + f1(n0.x) + ' ' + f1(n0.y) + 'V' + f1(nZ.y);
            nodes.forEach(function (n) { stops.push({ el: n, f: (box(n, ref).y - n0.y) / Math.max(1, nZ.y - n0.y) }); });
          }
        } else {
          var port = $('.hm-port', r), pb = box(port, ref), rb = box(r, ref), rad = 14, y1 = rb.t + 28;
          armD = curve(o.x, o.y, pb.x, pb.y, 0.55);
          /* port (top centre) -> across the top -> down the gutter through every node */
          inner = 'M' + f1(pb.x) + ' ' + f1(pb.y) + 'V' + f1(y1 - rad) + 'Q' + f1(pb.x) + ' ' + f1(y1) + ' ' + f1(pb.x - rad) + ' ' + f1(y1) +
            'H' + f1(n0.x + rad) + 'Q' + f1(n0.x) + ' ' + f1(y1) + ' ' + f1(n0.x) + ' ' + f1(y1 + rad) + 'V' + f1(nZ.y);
          var lead = (y1 - rad - pb.y) + Math.PI * rad / 2 + Math.max(0, (pb.x - rad) - (n0.x + rad)) + Math.PI * rad / 2;
          var total = lead + (nZ.y - (y1 + rad));
          stops.push({ el: port, f: 0 });
          nodes.forEach(function (n) { stops.push({ el: n, f: (lead + (box(n, ref).y - (y1 + rad))) / Math.max(1, total) }); });
        }
        var arm = mkPath(svg, armD, 'hm-arm r' + i);
        if (!tabs && i === 1) arm.style.stroke = 'url(#hm-fork-g)';
        var ip = inner ? mkPath(svg, inner, 'hm-inner r' + i) : null;
        specs.push({ i: i, arm: arm, inner: ip, stops: stops });
        if (!tabs && i === 1) {                          /* the professional arm turns gold as it enters the navy panel */
          var defs = document.createElementNS(NS, 'defs');
          defs.innerHTML = '<linearGradient id="hm-fork-g" gradientUnits="userSpaceOnUse" x1="0" y1="' + f1(rb.t - 1) + '" x2="0" y2="' + f1(rb.t + 1) + '"><stop offset="0" stop-color="#8b6b45"/><stop offset="1" stop-color="#c9a45c"/></linearGradient>';
          svg.insertBefore(defs, svg.firstChild);
        }
      });
      if (REDUCED || (entered && !mode)) return;
      if (!entered) { specs.forEach(function (s) { hide(s.arm); if (s.inner) hide(s.inner); }); return; }
      clearT();
      if (mode === 'enter') {
        specs.forEach(function (s) {
          draw(s.arm, 760, 120 + s.i * 70);
          if (s.inner) { draw(s.inner, 1300, 720 + s.i * 70); schedule(s, 1300, 720 + s.i * 70); }
          else lightAll(routes[s.i]);
        });
      } else if (mode === 'switch') {
        specs.forEach(function (s) {
          if (s.i !== on || !s.inner) return;
          unlight(routes[s.i]); draw(s.inner, 900, 60); schedule(s, 900, 60);
        });
      }
    }
    function setOn(i) {
      if (i === on) return;
      on = i; seg.setAttribute('data-on', String(i)); root.setAttribute('data-on', String(i));
      routes.forEach(function (r, k) { r.classList.toggle('hm-active', k === i); });
      roles(); layout('switch');
    }
    routes.forEach(function (r, i) {
      r.addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse' && !mq.matches) root.setAttribute('data-focus', String(i)); });
      r.addEventListener('pointerleave', function () { root.removeAttribute('data-focus'); });
    });
    roles(); layout(null);
    observeSize(root, function () { if (sizeOf(root) !== laid) layout(null); });
    if (mq.addEventListener) mq.addEventListener('change', roles);   /* geometry follows via the size observer */
    watch(root, function (still) {
      entered = true;
      if (still) { routes.forEach(lightAll); layout(null); return; }
      layout('enter');
    });
  }

  /* ---------- Module 1 -> 2 -> 3: the facts light their part of the line ---------- */
  function mods() {
    var m = $('.hm-mods'); if (!m) return;
    watch(m);
    $all('[data-hm-mod]').forEach(function (f) {
      f.addEventListener('pointerenter', function () { m.setAttribute('data-lit', f.getAttribute('data-hm-mod')); });
      f.addEventListener('pointerleave', function () { m.removeAttribute('data-lit'); });
    });
  }

  /* ---------- 3 · the tremor field: disturb it, watch it settle ---------- */
  function field() {
    var fig = $('.hm-field'); if (!fig || !L.tremor) return;
    var cv = $('canvas', fig); if (!cv) return;
    var api = L.tremor(cv, {
      lines: 9, top: 0.2, bottom: 0.78, colors: ['201,164,92', '243,232,210'], alpha: [0.32, 0.8], width: 1.35,
      amp: 7, wave: [150, 260], breath: 8, fade: 0, reach: 90, shiver: 9, settle: 2.3, source: fig, idlePulse: 6
    });
    if (!api) return;
    fig.classList.add('hm-live');
    if (REDUCED) return;
    var hint = $('.hm-field-hint', fig);
    if (hint) hint.textContent = FINE ? 'Move across the lines' : 'Drag across the lines';
    var used = false, timer = 0;
    var use = function () { if (!used) { used = true; fig.classList.add('hm-used'); } };
    fig.addEventListener('pointermove', use, { passive: true });
    fig.addEventListener('pointerdown', function (e) {
      use();
      var r = cv.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;
      api.poke(x, y);
      api.pulse(Math.max(-60, x - 120), clamp(Math.round(((y / Math.max(1, r.height)) - 0.2) / 0.58 * 8), 0, 8));
      clearTimeout(timer);
      if (e.pointerType !== 'mouse') timer = setTimeout(function () { api.poke(-1e4, -1e4); }, 700);
    });
  }

  /* ---------- 4 · photo strip: scrubber + previous / next ---------- */
  function strip() {
    var s = $('.hm-strip'); if (!s) return;
    watch(s);
    var bar = document.createElement('div'); bar.className = 'container hm-strip-bar';
    bar.innerHTML = '<span class="hm-strip-track" aria-hidden="true"><span class="hm-strip-thumb"></span></span>' +
      '<button type="button" class="hm-strip-btn hm-prev" aria-label="Previous photos">' + CHEV + '</button>' +
      '<button type="button" class="hm-strip-btn hm-next" aria-label="Next photos">' + CHEV + '</button>';
    s.parentNode.insertBefore(bar, s.nextSibling);
    var thumb = $('.hm-strip-thumb', bar), prev = $('.hm-prev', bar), next = $('.hm-next', bar), raf = 0;
    function upd() {
      raf = 0;
      var max = s.scrollWidth - s.clientWidth, wk = s.scrollWidth > 0 ? clamp(s.clientWidth / s.scrollWidth, 0.05, 1) : 1, k = max > 0 ? clamp(s.scrollLeft / max, 0, 1) : 0;
      bar.hidden = max < 8;
      thumb.style.width = (wk * 100).toFixed(2) + '%';
      thumb.style.transform = 'translateX(' + (k * (1 / wk - 1) * 100).toFixed(2) + '%)';
      prev.disabled = s.scrollLeft < 4; next.disabled = s.scrollLeft > max - 4;
    }
    function step(dir) { s.scrollBy({ left: dir * Math.max(260, s.clientWidth * 0.72), behavior: REDUCED ? 'auto' : 'smooth' }); }
    prev.addEventListener('click', function () { step(-1); });
    next.addEventListener('click', function () { step(1); });
    s.addEventListener('scroll', function () { if (!raf) raf = requestAnimationFrame(upd); }, { passive: true });
    observeSize(s, upd);
    upd();
  }

  /* ---------- 6 · events: the next dates on a time rail that starts today ---------- */
  function pday(iso) { var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso || ''); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null; }
  function rail() {
    var sec = $('.hm-events'); if (!sec) return;
    var grid = $('[data-events-preview]', sec), rl = $('.hm-rail', sec);
    if (!grid || !rl) return;
    var cards = $all('.event-card', grid), by = {}, items = [];
    (window.TRE_EVENTS || []).forEach(function (e) { if (e && e.slug) by[e.slug] = e; });
    cards.forEach(function (c) {
      var a = $('h3 a', c), m = a ? /[?&]id=([^&#]+)/.exec(a.getAttribute('href') || '') : null;
      var ev = m ? by[decodeURIComponent(m[1])] : null, d = ev ? pday(ev.start) : null;
      if (d) items.push({ card: c, date: d });
    });
    if (!items.length) { watch(sec); return; }
    var now = new Date(), yr = now.getFullYear(), t0 = new Date(yr, now.getMonth(), now.getDate()).getTime();
    var t1 = Math.max.apply(null, items.map(function (x) { return x.date.getTime(); }));
    if (t1 - t0 < 7 * 864e5) t1 = t0 + 7 * 864e5;
    var fx = function (t) { return clamp((t - t0) / (t1 - t0), 0, 1); };
    var h = '<span class="hm-rail-line"></span><span class="hm-rail-start"><i></i><em>Today</em></span>';
    for (var d = new Date(yr, now.getMonth() + 1, 1); d.getTime() < t1; d = new Date(d.getFullYear(), d.getMonth() + 1, 1)) {
      var f = fx(d.getTime());
      if (f > 0.05 && f < 0.97) h += '<span class="hm-rail-tick" style="left:' + (f * 100).toFixed(2) + '%"><em>' + MON[d.getMonth()] + (d.getMonth() === 0 ? ' ' + d.getFullYear() : '') + '</em></span>';
    }
    items.forEach(function (it, i) {
      it.f = fx(it.date.getTime());
      var lab = it.date.getDate() + ' ' + MON[it.date.getMonth()] + (it.date.getFullYear() !== yr ? ' ' + it.date.getFullYear() : '');
      it.delay = Math.round(at(it.f, 1100, 100));
      h += '<span class="hm-rail-node" style="left:' + (it.f * 100).toFixed(2) + '%;--d:' + it.delay + 'ms"><span>' + lab + '</span></span>';
    });
    rl.innerHTML = h;
    var nodes = $all('.hm-rail-node', rl), ticks = $all('.hm-rail-tick', rl), links = mkSvg(rl, 'hm-rail-links');
    var mq = window.matchMedia('(max-width: 980px)'), entered = false, laid = '';
    function tidy() {                                   /* keep labels inside the rail and off each other */
      var W = rl.clientWidth, prevR = -1e9, tprev = -1e9, todayR = ($('.hm-rail-start em', rl).getBoundingClientRect().width || 0) + 8;
      nodes.forEach(function (n, i) {
        n.classList.remove('hm-start', 'hm-end', 'hm-up');
        var lw = n.firstChild.getBoundingClientRect().width, x = items[i].f * W, l = x - lw / 2;
        if (l < 0) { n.classList.add('hm-start'); l = x - 8; } else if (x + lw / 2 > W) { n.classList.add('hm-end'); l = x - lw + 8; }
        if (l < Math.max(prevR, i === 0 ? todayR : -1e9) + 10) { n.classList.add('hm-up'); }
        else prevR = l + lw;
      });
      ticks.forEach(function (t) {
        t.classList.remove('hm-mute');
        var e = t.firstChild, r = e.getBoundingClientRect(), x = parseFloat(t.style.left) / 100 * W;
        if (x - r.width / 2 < tprev + 8) t.classList.add('hm-mute'); else tprev = x + r.width / 2;
      });
    }
    function wire(mode) {
      laid = sizeOf(sec);
      fit(links, rl); items.forEach(function (it) { it.link = null; });
      if (mq.matches) return;
      var ref = rl.getBoundingClientRect();
      items.forEach(function (it, i) {
        var n = box(nodes[i], ref), c = box(it.card, ref);
        it.link = mkPath(links, curve(n.x, n.y + 9, c.x, c.t - 2, 0.5), 'l' + i);
        if (REDUCED) return;
        if (mode === 'enter') draw(it.link, 700, it.delay + 320);
        else if (!entered) hide(it.link);
      });
    }
    function hot(i, v) { var it = items[i]; if (!it) return; it.card.classList.toggle('hm-hot', v); nodes[i].classList.toggle('hm-hot', v); if (it.link) it.link.classList.toggle('hm-lit', v); }
    function pad() { return parseFloat(getComputedStyle(grid).paddingLeft) || 0; }
    nodes.forEach(function (n, i) {
      n.addEventListener('pointerenter', function () { hot(i, true); });
      n.addEventListener('pointerleave', function () { hot(i, false); });
      n.addEventListener('click', function () {
        var c = items[i].card;
        if (mq.matches) grid.scrollTo({ left: c.offsetLeft - pad(), behavior: REDUCED ? 'auto' : 'smooth' });
        else { hot(i, true); later(1400, function () { hot(i, false); }); }
      });
    });
    items.forEach(function (it, i) {
      it.card.addEventListener('pointerenter', function () { hot(i, true); });
      it.card.addEventListener('pointerleave', function () { hot(i, false); });
    });
    var sraf = 0;
    function follow() {
      sraf = 0;
      var x = grid.scrollLeft, p = pad(), best = 0, bd = 1e9;
      items.forEach(function (it, i) { var dd = Math.abs(it.card.offsetLeft - p - x); if (dd < bd) { bd = dd; best = i; } });
      nodes.forEach(function (n, i) { n.classList.toggle('hm-active', mq.matches && i === best); });
    }
    grid.addEventListener('scroll', function () { if (!sraf) sraf = requestAnimationFrame(follow); }, { passive: true });
    tidy(); wire(null); follow();
    observeSize(sec, function () { if (sizeOf(sec) !== laid) { tidy(); wire(null); follow(); } });
    watch(sec, function (still) { entered = true; wire(still ? null : 'enter'); });
  }

  /* ---------- 7 · the practitioner web: spokes from the promise to what it offers ---------- */
  function web() {
    var root = $('[data-hm-web]'); if (!root) return;
    var core = $('.hm-web-core', root), ring = $('.hm-web-ring', root), items = $all('.hm-web-item', root);
    if (!core || !items.length) return;
    var svg = mkSvg(root, 'hm-web-svg'), mq = window.matchMedia('(max-width: 1060px)'), entered = false, laid = '', paths = [];
    var nodes = items.map(function (it) { return $('.hm-node', it); });
    function layout(mode) {
      laid = sizeOf(root); fit(svg, root); paths = [];
      var ref = root.getBoundingClientRect(), anim = mode === 'enter' && !REDUCED;
      if (mq.matches) {
        var c = box(core, ref), a = box(nodes[0], ref), z = box(nodes[nodes.length - 1], ref), y0 = c.b;
        var p = mkPath(svg, 'M' + f1(a.x) + ' ' + f1(y0) + 'V' + f1(z.y), 'hm-spoke');
        paths = items.map(function () { return null; });
        if (anim) {
          draw(p, 1200, 300);
          nodes.forEach(function (n) { later(at((box(n, ref).y - y0) / Math.max(1, z.y - y0), 1200, 300) - 40, function () { n.classList.add('hm-lit'); }); });
        } else if (!entered && !REDUCED) hide(p);
      } else {
        var rr = box(ring && ring.offsetParent ? ring : core, ref), R = rr.w / 2;
        nodes.forEach(function (n, i) {
          var nb = box(n, ref), ang = Math.atan2(nb.y - rr.y, nb.x - rr.x), sx = rr.x + Math.cos(ang) * R, sy = rr.y + Math.sin(ang) * R, mx = (sx + nb.x) / 2;
          var q = mkPath(svg, 'M' + f1(sx) + ' ' + f1(sy) + 'C' + f1(mx) + ' ' + f1(sy) + ' ' + f1(mx) + ' ' + f1(nb.y) + ' ' + f1(nb.x) + ' ' + f1(nb.y), 'hm-spoke s' + i);
          paths.push(q);
          if (anim) { draw(q, 900, 380 + i * 110); later(380 + i * 110 + 560, function () { n.classList.add('hm-lit'); }); }
          else if (!entered && !REDUCED) hide(q);
        });
      }
    }
    items.forEach(function (it, i) {
      it.addEventListener('pointerenter', function () { if (paths[i]) paths[i].classList.add('hm-lit'); });
      it.addEventListener('pointerleave', function () { if (paths[i]) paths[i].classList.remove('hm-lit'); });
    });
    layout(null);
    observeSize(root, function () { if (sizeOf(root) !== laid) layout(null); });
    watch(root, function (still) {
      entered = true;
      if (still) { nodes.forEach(function (n) { n.classList.add('hm-lit'); }); layout(null); return; }
      layout('enter');
    });
  }

  function init() {
    L = window.TRELayer || {};
    var mm = function (q) { return !!(window.matchMedia && window.matchMedia(q).matches); };
    REDUCED = typeof L.reduced === 'boolean' ? L.reduced : mm('(prefers-reduced-motion: reduce)');
    FINE = typeof L.fine === 'boolean' ? L.fine : mm('(hover: hover) and (pointer: fine)');
    safe(fork); safe(mods); safe(function () { watch($('.hm-checks')); }); safe(field); safe(strip);
    safe(function () { watch($('.hm-people-grid')); }); safe(rail); safe(web);
    safe(function () { watch($('.hm-read-grid')); }); safe(function () { watch($('.hm-band')); });
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(function () { relayouts.forEach(function (fn) { safe(fn); }); });
    window.addEventListener('beforeprint', function () {
      $all('.hm-armed').forEach(function (el) { el.classList.add('hm-in'); });
      $all('.hm-node,.hm-port').forEach(function (n) { n.classList.add('hm-lit'); });
      $all('.hm-row').forEach(function (r) { r.classList.add('hm-shown'); });
      $all('.hm-fork-svg path,.hm-rail-links path,.hm-web-svg path').forEach(function (p) { p.style.transition = 'none'; p.style.strokeDashoffset = '0'; });
    });
  }
  document.addEventListener('DOMContentLoaded', function () { setTimeout(init, 0); });
})();
